import { describe, expect, it } from 'vitest';
import type { InputAction, InputSnapshot, PointerSnapshot } from '../input/InputManager';
import { CameraDirector } from './CameraDirector';
import type { HoleFraming } from './CameraModes';
import { CAMERA_MODE_SETTINGS, cameraModeSettings, framingCenter, isCameraMode, overviewPose } from './CameraModes';
import { cameraPoseDistance } from './CameraPose';

const FRAME = 1 / 60;

const FRAMING: HoleFraming = {
  bounds: { min: { x: -4, y: 0, z: -2 }, max: { x: 4, y: 4, z: 22 } },
  spawn: { x: 0, y: 0.2, z: 0 },
  cup: { x: 0, y: 0.2, z: 20 },
};

function snapshot(
  options: { down?: InputAction[]; pressed?: InputAction[]; pointer?: Partial<PointerSnapshot> } = {},
): InputSnapshot {
  const down = options.down ?? [];
  const pressed = options.pressed ?? [];
  return {
    pointer: { x: 0, y: 0, deltaX: 0, deltaY: 0, wheel: 0, primaryDown: false, ...options.pointer },
    isDown: (action) => down.includes(action),
    wasPressed: (action) => pressed.includes(action),
    wasReleased: () => false,
  };
}

function run(director: CameraDirector, frames: number, input?: InputSnapshot) {
  let pose = director.pose;
  for (let index = 0; index < frames; index += 1) pose = director.update(FRAME, input);
  return pose;
}

function orbitRadius(position: { x: number; z: number }, target: { x: number; z: number }): number {
  return Math.hypot(position.x - target.x, position.z - target.z);
}

describe('camera mode settings', () => {
  it('recognises the four modes and ignores undefined overrides', () => {
    expect(isCameraMode('overview')).toBe(true);
    expect(isCameraMode('cinematic')).toBe(false);
    const tuned = cameraModeSettings('aim', { distance: undefined, fov: 40 });
    expect(tuned.distance).toBe(CAMERA_MODE_SETTINGS.aim.distance);
    expect(tuned.fov).toBe(40);
    expect(cameraModeSettings('aim').fov).toBe(CAMERA_MODE_SETTINGS.aim.fov);
  });
});

describe('overview framing', () => {
  it('looks at the middle of the hole from behind the tee', () => {
    const pose = overviewPose(FRAMING);
    const center = framingCenter(FRAMING);
    expect(center).toEqual({ x: 0, y: 0.2, z: 10 });
    expect(pose.target).toEqual(center);
    expect(pose.position.x).toBeCloseTo(0, 6);
    expect(pose.position.z).toBeLessThan(pose.target.z);
    expect(pose.position.y).toBeGreaterThan(8);
  });

  it('stands further back for a larger level', () => {
    const wide = overviewPose({
      ...FRAMING,
      bounds: { min: { x: -40, y: 0, z: -40 }, max: { x: 40, y: 4, z: 40 } },
    });
    expect(orbitRadius(wide.position, wide.target)).toBeGreaterThan(
      orbitRadius(overviewPose(FRAMING).position, overviewPose(FRAMING).target),
    );
  });
});

describe('CameraDirector modes', () => {
  it('starts aiming and reports only real mode changes', () => {
    const director = new CameraDirector({ framing: FRAMING, focus: FRAMING.spawn });
    expect(director.mode).toBe('aim');
    expect(director.setMode('follow')).toBe(true);
    expect(director.setMode('follow')).toBe(false);
    expect(director.mode).toBe('follow');
    expect(director.setMode('overview')).toBe(true);
    expect(director.mode).toBe('overview');
  });

  it('keeps the aim yaw when the shot hands over to the follow camera', () => {
    const director = new CameraDirector({ framing: FRAMING, focus: FRAMING.spawn });
    const yaw = director.yaw;
    director.setMode('follow');
    expect(director.yaw).toBeCloseTo(yaw, 10);
  });

  it('drifts around the hole in overview and blends back to the ball', () => {
    const director = new CameraDirector({ framing: FRAMING, focus: FRAMING.spawn, initialMode: 'overview' });
    const start = director.pose;
    expect(start.target.z).toBeCloseTo(10, 6);

    const drifted = run(director, 120);
    expect(Math.abs(drifted.position.x - start.position.x)).toBeGreaterThan(1);
    expect(orbitRadius(drifted.position, drifted.target)).toBeCloseTo(orbitRadius(start.position, start.target), 0);

    director.setMode('aim');
    const firstFrame = director.update(FRAME);
    expect(director.isTransitioning).toBe(true);
    expect(cameraPoseDistance(drifted, firstFrame)).toBeLessThan(2);

    const settled = run(director, 240);
    expect(director.isTransitioning).toBe(false);
    expect(settled.target.z).toBeCloseTo(FRAMING.spawn.z, 1);
    expect(settled.position.y).toBeLessThan(6);
  });
});

describe('CameraDirector transitions', () => {
  it('eases towards a new focus over several frames instead of teleporting', () => {
    const director = new CameraDirector({ framing: FRAMING, focus: FRAMING.spawn });
    run(director, 30);
    const before = director.pose;

    director.focusOn({ x: 0, y: 0.2, z: 18 });
    const firstFrame = director.update(FRAME);
    expect(cameraPoseDistance(before, firstFrame)).toBeGreaterThan(0);
    expect(firstFrame.target.z).toBeLessThan(3);

    const settled = run(director, 300);
    expect(settled.target.z).toBeCloseTo(18, 1);
    expect(settled.position.z).toBeLessThan(settled.target.z);
  });

  it('switches to the free camera on WASD and slides back to the ball on R', () => {
    const director = new CameraDirector({ framing: FRAMING, focus: FRAMING.spawn });
    run(director, 30);

    const free = run(director, 60, snapshot({ down: ['camera-forward'] }));
    expect(director.mode).toBe('free');
    expect(free.target.z).toBeGreaterThan(1);

    const afterReset = director.update(FRAME, snapshot({ pressed: ['camera-reset'] }));
    expect(director.mode).toBe('aim');
    expect(director.isTransitioning).toBe(true);
    const travelled = cameraPoseDistance(free, afterReset);
    expect(travelled).toBeGreaterThan(0);
    expect(travelled).toBeLessThan(1);

    const settled = run(director, 300);
    expect(Math.abs(settled.target.z - FRAMING.spawn.z)).toBeLessThan(0.2);
  });
});
